  messages[failureCode] ??
  'عملیات دعوت امن تکمیل نشد. جزئیات خصوصی در خروجی نمایش داده نمی‌شود.';

return [
  {
    json: {
      success: false,
      failureCode,
      retryable: false,
      output: `<p>${message}</p><p><strong>کد وضعیت:</strong> ${failureCode}</p>`,
    },
  },
];

